"""Record the side network on generated bytes, without opening any film."""
from __future__ import annotations

import argparse
import importlib.util
from pathlib import Path
import platform
import sys

sys.dont_write_bytecode = True
import numpy as np
import PIL
from PIL import Image
import torch


def path_module(name, path, source=None):
    path = Path(path).resolve(strict=True)
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise ValueError("Cannot load the requested local module")
    module = importlib.util.module_from_spec(spec)
    # Execute the checked source bytes rather than an unrelated cached bytecode file.
    source = path.read_bytes() if source is None else source
    exec(compile(source, str(path), "exec"), module.__dict__)
    return module


pack = path_module("side_packet_preparation", Path(__file__).with_name("pack_side_weights.py"))
SOURCE_HASHES = {
    "model.py": "2a491d910f2bf1c8894259138f42de7568c97b34c4138af9441a7bd34a4032e0",
    "prepare_data.py": "507973a74831550f1ed5d243ebad0ca269734c1a5f9d4529f7b74080ea06ee85",
    "predict.py": "628c7a432d32f102a715c4e934aec23f166178dda3d749e7524805f487187055",
}
PIL_VERSION = "13.0.0"


def reference_modules(model_dir):
    root = Path(model_dir).resolve(strict=True)
    sources = {}
    for name, expected in SOURCE_HASHES.items():
        sources[name] = pack.regular_bytes(root / name)
        if pack.digest(sources[name]) != expected:
            raise ValueError(f"Reference module hash differs: {name}")
    # Neither module needs a search-path change or imports the dataset at import time.
    model = path_module("side_reference_model", root / "model.py", sources["model.py"])
    preparation = path_module("side_reference_resize", root / "prepare_data.py", sources["prepare_data.py"])
    if pack.json_bytes(model.MODEL_SCHEMA) != pack.json_bytes(pack.MODEL_SCHEMA):
        raise ValueError("Reference model schema differs")
    return model, preparation


def xorshift32(seed):
    state = seed
    while True:
        state = (state ^ (state << 13)) & 0xffffffff
        state = (state ^ (state >> 17)) & 0xffffffff
        state = (state ^ (state << 5)) & 0xffffffff
        yield state


def input_bytes(height, width):
    stream = xorshift32(20261113)
    return np.fromiter((next(stream) >> 24 for _ in range(height * width)),
                       dtype=np.uint8, count=height * width).reshape(height, width)


def synthetic_tensors():
    stream = xorshift32(17)
    tensors = {}
    for name, shape in pack.tensor_shapes().items():
        count = int(np.prod(shape))
        if name.endswith("weight"):
            values = np.fromiter((((next(stream) >> 24) - 128) * 2**-14 for _ in range(count)),
                                 dtype="<f4", count=count).reshape(shape)
        else:
            values = np.zeros(shape, dtype="<f4")
        tensors[name] = values
    return tensors


def use_folded_tensors(net, tensors):
    """Remove BN entirely so identity does not introduce a second rounding."""
    for name, shape in pack.tensor_shapes().items():
        layer_name, part = name.rsplit(".", 1)
        block, index = layer_name.split(".")
        layer = getattr(net, block)[int(index)]
        value = torch.from_numpy(tensors[name].copy()).reshape(shape)
        setattr(layer, part, torch.nn.Parameter(value, requires_grad=False))
    for block, _, _ in pack.BLOCKS:
        getattr(net, block)[1] = torch.nn.Identity()
        getattr(net, block)[4] = torch.nn.Identity()
    return net.eval()


def activation(tensor):
    values = tensor.detach().cpu().double().numpy()[0]
    if not np.isfinite(values).all():
        raise ValueError("Nonfinite reference activation")
    channels, height, width = values.shape
    indices = sorted({0, values.size // 7, values.size // 2, values.size - 1,
                      (height // 2) * width + width // 2,
                      (channels - 1) * height * width + (height // 2) * width + width // 2})
    return {"shape": list(values.shape), "min": float(values.min()), "max": float(values.max()),
            "sum": float(values.sum()), "absSum": float(np.abs(values).sum()),
            "squareSum": float(np.square(values).sum()),
            "samples": [{"index": int(i), "value": float(values.flat[i])} for i in indices]}


def reading(net, model, raw):
    captured, hooks = {}, []
    for block, _, _ in pack.BLOCKS:
        for conv, relu in ((0, 2), (3, 5)):
            name = f"{block}.{conv}"
            hooks.append(getattr(net, block)[relu].register_forward_hook(
                lambda module, given, got, name=name: captured.__setitem__(name, activation(got))))
    for layer, hook_at in ((0, 1), (2, 2)):
        name = f"landmarks.{layer}"
        hooks.append(net.landmarks[hook_at].register_forward_hook(
            lambda module, given, got, name=name: captured.__setitem__(name, activation(got))))
    uncentred = raw.astype(np.float32) / np.float32(255)
    given = torch.from_numpy(uncentred)[None, None]
    try:
        with torch.inference_mode():
            logits = net(given)
            points = model.decode_heatmaps(logits).cpu().numpy()[0]
    finally:
        for hook in hooks:
            hook.remove()
    if points.shape != (5, 4, 2) or not np.isfinite(points).all():
        raise ValueError("Invalid decoded reference points")
    return {"input": {"shape": [1, *raw.shape], "bytesSha256": pack.digest(raw.tobytes()),
                      "centredF32Sha256": pack.digest((uncentred - np.float32(.5)).astype("<f4").tobytes())},
            "layers": captured, "points": points.tolist()}, logits


def resize_answers(preparation):
    if PIL.__version__ != PIL_VERSION:
        raise ValueError(f"Resize answers require Pillow {PIL_VERSION}")
    cases = (("ramp-up-odd-padding", "ramp", 3, 2, 8, 8),
             ("checker-down", "checker", 9, 7, 4, 4),
             ("ramp-unchanged-x", "ramp", 5, 3, 5, 7),
             ("ramp-unchanged-y", "ramp", 3, 5, 7, 5),
             ("checker-unchanged", "checker", 4, 4, 4, 4),
             ("tie-even-down", "ramp", 5, 4, 10, 2),
             ("tie-even-up", "checker", 7, 4, 10, 2),
             ("ramp-vertical-odd-padding", "ramp", 2, 3, 8, 8))
    records = []
    for name, pattern, width, height, target_width, target_height in cases:
        yy, xx = np.indices((height, width))
        raw = (((xx + yy) % 2) * 255 if pattern == "checker" else (xx * 37 + yy * 53) % 256).astype(np.uint8)
        result = preparation.letterbox_image(Image.fromarray(raw), size=(target_width, target_height))
        canvas = np.rint(result["image"][0] * 255).astype(np.uint8)
        records.append({"name": name, "inputSize": [width, height], "inputBytes": raw.reshape(-1).tolist(),
                        "targetSize": [target_width, target_height],
                        "resizedSize": result["resized_size"].tolist(),
                        "padding": result["padding"].tolist(), "affine": result["affine"].tolist(),
                        "inverseAffine": result["inverse_affine"].tolist(),
                        "outputBytes": canvas.reshape(-1).tolist(), "outputSha256": pack.digest(canvas.tobytes())})
    return records


def make_answer(model_dir, kind):
    if kind not in ("synthetic", "trained"):
        raise ValueError("Unknown answer kind")
    torch.set_num_threads(3)
    # This public setter avoids importing the compiler and creating its disk cache.
    torch.set_deterministic_debug_mode("error")
    model, preparation = reference_modules(model_dir)
    net = model.SideLandmarkNet().cpu()
    root = Path(model_dir).resolve(strict=True)
    hashes = {name: pack.digest(pack.regular_bytes(root / name))
              for name in (*SOURCE_HASHES, "model_card.json", "selection.json")}
    if kind == "synthetic":
        tensors = synthetic_tensors()
        net = use_folded_tensors(net, tensors)
        weight_payload = b"".join(tensors[name].tobytes() for name in pack.tensor_shapes())
        weights = {"kind": kind, "seed": 17, "payloadSha256": pack.digest(weight_payload),
                   "rule": "One xorshift32 stream in packet order; weight=((next>>24)-128)*2^-14; bias=0 consumes no stream; BN removed (identity)."}
        height, width = 128, 128
    else:
        net.load_state_dict(pack.load_checkpoint(root), strict=True)
        net.eval()
        weights = {"kind": kind, "checkpointSha256": pack.CHECKPOINT_SHA256,
                   "rule": "Fixed checkpoint; original unfused CPU eval model."}
        hashes[pack.CHECKPOINT] = pack.CHECKPOINT_SHA256
        height, width = 512, 384
    recorded, _ = reading(net, model, input_bytes(height, width))
    answer = {"format": "side-finder-known-answer", "version": 1, "kind": kind,
              "generator": {"algorithm": "xorshift32", "inputSeed": 20261113,
                            "rule": "Row-major; state^=state<<13; state^=state>>17; state^=state<<5; mask u32 after each; byte=state>>24.",
                            "normalisation": "f32(byte)/255; source forward subtracts 0.5 exactly once"},
              "weights": weights, "sourceHashes": hashes,
              "software": {"python": platform.python_version(), "torch": torch.__version__,
                           "numpy": np.__version__, "pillow": PIL.__version__, "device": "cpu", "threads": 3},
              "activationRule": "CHW row-major; block convolutions after BN/ReLU; landmarks.0 after ReLU; landmarks.2 logits; statistics use f64.",
              "levels": pack.MODEL_SCHEMA["levels"], "corners": pack.MODEL_SCHEMA["corners"],
              "coordinateSystem": "Input pixel centres; x right, y down; ((cell+.5)*4-.5); no clipping",
              "tolerances": {"activationAbsolute": 2e-4, "activationRelative": 1e-4, "pointModelPx": .01, "resizeBytes": 0},
              **recorded}
    if kind == "synthetic":
        answer["resize"] = {"pillow": PIL_VERSION, "filter": "BILINEAR", "cases": resize_answers(preparation)}
    return answer


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model-dir", required=True, type=Path)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--kind", required=True, choices=("synthetic", "trained"))
    args = parser.parse_args()
    answer = make_answer(args.model_dir, args.kind)
    data = pack.json_bytes(answer)
    pack.atomic_write(args.out, data, args.model_dir)
    print(pack.json_bytes({"kind": args.kind, "bytes": len(data), "sha256": pack.digest(data),
                           "layers": len(answer["layers"]), "points": 20}).decode().strip())


if __name__ == "__main__":
    main()
